$ErrorActionPreference='Stop'
function Need($ok,[string]$why){if(!$ok){throw $why}}
function Sha([byte[]]$body){$h=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($h.ComputeHash($body))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}}
function Regular([string]$path){Need (Test-Path -LiteralPath $path -PathType Leaf) ('FILE_MISSING_'+[IO.Path]::GetFileName($path));Need (!((Get-Item -Force -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint)) 'FILE_REPARSE_REFUSED'}
function AtomicWrite([string]$path,[byte[]]$body){$tmp=$path+'.new-'+[guid]::NewGuid().ToString('N');try{[IO.File]::WriteAllBytes($tmp,$body);[IO.File]::Replace($tmp,$path,[System.Management.Automation.Language.NullString]::Value)}finally{if(Test-Path -LiteralPath $tmp){Remove-Item -LiteralPath $tmp -Force}}}
$root='F:\CABAL_291_TEST'
Need ($env:OS -eq 'Windows_NT' -and [Environment]::Is64BitProcess) 'WINDOWS_X64_POWERSHELL_REQUIRED'
Need (!(Get-Process -Name CabalMain -ErrorAction SilentlyContinue)) 'AIZVER_SPELI_PIRMS_ATJAUNINAJUMA'
foreach($item in @(
 @('Bin\x64\CabalMain.exe','52e7956d4781fea1f0369cac8ab1eac4c3ddec2d1977c6557be53ec2b79885d9'),
 @('Bin\x64\libogg.dll','ceafa8291dcf090856a215285114270fea1a8978bc2d2b26b33bcb7b3ac5c2a9'),
 @('Bin\x64\d3d9.dll','216058f9320d0667d551f4cea840ee539396449ef8c8e89fe481e4f0ddb628ae'),
 @('Data\quest.enc','c298999da93d3d1c3e415b1618efeda80362e7247945e26226090a29ee18ea3d')
)){$path=Join-Path $root $item[0];Regular $path;Need ((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash -eq $item[1]) ('ORIGINAL_FILE_DIFFERS_'+$item[0])}
$own=Join-Path $root '.ep36-runtime'
Need (Test-Path -LiteralPath $own -PathType Container) 'INSTALLETAIS_CLIENT291_PROFILS_NAV_ATRASTS'
Need (!((Get-Item -Force -LiteralPath $own).Attributes -band [IO.FileAttributes]::ReparsePoint)) 'RUNTIME_REPARSE_REFUSED'
$activePath=Join-Path $own 'active.json';Regular $activePath
Need (!((Get-Item -Force -LiteralPath $activePath).Attributes -band [IO.FileAttributes]::ReadOnly)) 'ACTIVE_PROFILE_READONLY'
$before=[IO.File]::ReadAllBytes($activePath);$active=[Text.Encoding]::UTF8.GetString($before)|ConvertFrom-Json
Need ($active.Profile -match '^profile-[a-f0-9-]+$') 'RUNTIME_PROFILE_PATH_INVALID'
$oldProfile=Join-Path $own $active.Profile
Need (!((Get-Item -Force -LiteralPath $oldProfile).Attributes -band [IO.FileAttributes]::ReparsePoint)) 'PROFILE_REPARSE_REFUSED'
$required=@('Client291-Runtime.cs','Launch-Client.ps1','LauncherHost.cs','client291-profile.json','Client291-WorldBridge.bin','Client291-CharacterListBridge.bin','Client291-CloseObserver.bin')
$names=@($active.Files.PSObject.Properties|ForEach-Object{$_.Name})
Need (@(Compare-Object $required $names).Count -eq 0) 'OWN_PROFILE_MEMBER_SET_DIFFERS'
foreach($p in $active.Files.PSObject.Properties){
 $path=Join-Path $oldProfile $p.Name;Regular $path
 Need ((Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash -eq $p.Value) ('RUNTIME_FILE_CHANGED_'+$p.Name)
}
$launcher=Join-Path $oldProfile 'Launcher.exe';Regular $launcher
Need ((Get-FileHash -LiteralPath $launcher -Algorithm SHA256).Hash -eq $active.LauncherSHA) 'OWN_LAUNCHER_CHANGED'
$manifest=Get-Content -Raw -LiteralPath (Join-Path $oldProfile 'client291-profile.json')|ConvertFrom-Json
Need (($manifest.TargetRoot -replace '\\+','\') -eq 'F:\CABAL_291_TEST') 'PROFILE_TARGET_ROOT_DIFFERS'
$oldWorld=$active.Files.'Client291-WorldBridge.bin'.ToLowerInvariant()
Need ($manifest.WorldBridge.sha256 -eq $oldWorld) 'WORLD_MANIFEST_DIFFERS'
$world=[Convert]::FromBase64String('');$newWorld='fb7eb7cdd7f854e80ca8c4042be192f2040acae187a939db32b7ec35a31b05d3'
Need ((Sha $world) -eq $newWorld -and $world.Length -eq 16372) 'WORLD_UPDATE_PAYLOAD_DIFFERS'
Need ($oldWorld -in @('0d842f080dc4471f96a9abee0f32d72bb5f7d50129287bbf583c302dd4116220','f4d82f65110b96698a9cc6bc8cb6d0b65db376612659611c15b5651a76a7e6c6',$newWorld)) 'UNREVIEWED_WORLD_BRIDGE_PROFILE'
$runtimePath=Join-Path $oldProfile 'Client291-Runtime.cs'
$runtimeBytes=[IO.File]::ReadAllBytes($runtimePath);$runtime=[Text.Encoding]::UTF8.GetString($runtimeBytes)
$pattern='(?m)(const string WorldBridgeCodeSHA=")([0-9a-f]{64})(";)'
$matches=[regex]::Matches($runtime,$pattern)
Need ($matches.Count -eq 1 -and $matches[0].Groups[2].Value -eq $oldWorld) 'WORLD_RUNTIME_CONSTANT_DIFFERS'
if($oldWorld -eq $newWorld){'QUEST_PACKET_FIX_JAU_AKTIVS';'PALAIDEJS='+$launcher;return}
$match=$matches[0].Groups[2]
$updated=$runtime.Substring(0,$match.Index)+$newWorld+$runtime.Substring($match.Index+$match.Length)
$updatedBytes=[Text.Encoding]::UTF8.GetBytes($updated)
Need ((Sha ([Text.Encoding]::UTF8.GetBytes($updated.Replace($newWorld,$oldWorld)))) -eq (Sha $runtimeBytes)) 'UNRELATED_RUNTIME_BYTES_CHANGED'
$compiler=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
Need (Test-Path -LiteralPath $compiler -PathType Leaf) 'WINDOWS_FRAMEWORK_COMPILER_MISSING'
'QUEST_DUNGEON_PACKET_V1; PARBAUDU_TESTA_SERVERA_PROFILU; NEPARSTARTESU'
$remote=[Text.Encoding]::ASCII.GetString([Convert]::FromBase64String(''))
$result=@($remote|ssh root@192.168.56.101 python3 -)
$result|ForEach-Object{Write-Output $_}
Need ($LASTEXITCODE -eq 0 -and @($result|Where-Object{$_ -eq 'QUEST_PACKET_PREFLIGHT_OK; PROFILES=1141'}).Count -eq 1) 'QUEST_PACKET_SERVER_PROFILE_NOT_CONFIRMED; NEKAS_NAV_MAINITS'
$name='profile-fb7eb7cdd7f8-'+[guid]::NewGuid().ToString('N').Substring(0,8)
$profile=Join-Path $own $name
Need (!(Test-Path -LiteralPath $profile)) 'NEW_PROFILE_COLLISION'
[void][IO.Directory]::CreateDirectory($profile)
foreach($p in $active.Files.PSObject.Properties){$dest=Join-Path $profile $p.Name;[IO.File]::Copy((Join-Path $oldProfile $p.Name),$dest);Need ((Get-FileHash -LiteralPath $dest -Algorithm SHA256).Hash -eq $p.Value) 'SOURCE_PROFILE_CHANGED_DURING_COPY'}
[IO.File]::Copy($launcher,(Join-Path $profile 'Launcher.exe'))
[IO.File]::WriteAllBytes((Join-Path $profile 'Client291-Runtime.cs'),$updatedBytes)
[IO.File]::WriteAllBytes((Join-Path $profile 'Client291-WorldBridge.bin'),$world)
$newMetadata=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))|ConvertFrom-Json
$manifest.WorldBridge=$newMetadata
$manifest|Add-Member -NotePropertyName QuestDungeonPackets -NotePropertyValue ([ordered]@{Version=1;Type2ProgressBytes=0;ExactProfiles=1141;CorrectedScalarDungeonProfiles=54;FullCatalogueAlignment=$false;WindowsGameplay='PENDING'}) -Force
[IO.File]::WriteAllText((Join-Path $profile 'client291-profile.json'),($manifest|ConvertTo-Json -Depth 32),[Text.Encoding]::UTF8)
$launchPath=Join-Path $profile 'Launch-Client.ps1'
$launch=[IO.File]::ReadAllText($launchPath).Replace('QuestNativeZeroProgressProfiles=46','QuestNativeZeroProgressProfiles=0').Replace('Client291-LoginStart-v4_9_8-','Client291-QuestPacket-v1-')
[IO.File]::WriteAllText($launchPath,$launch,[Text.Encoding]::UTF8)
'PARBAUDU_MUSU_RUNTIME_KOMPILACIJU; SPELE_NETIKS_PALAISTA'
& $compiler /nologo /target:library /platform:x64 /optimize+ ("/out:"+(Join-Path $profile 'Runtime-CompileCheck.dll')) (Join-Path $profile 'Client291-Runtime.cs')
Need ($LASTEXITCODE -eq 0 -and (Test-Path -LiteralPath (Join-Path $profile 'Runtime-CompileCheck.dll'))) 'QUEST_RUNTIME_BUILD_FAILED; VECAS_PROFILS_SAGLABATS'
$hashes=[ordered]@{}
foreach($p in $active.Files.PSObject.Properties){$hashes[$p.Name]=(Get-FileHash -LiteralPath (Join-Path $profile $p.Name) -Algorithm SHA256).Hash.ToLowerInvariant()}
foreach($member in @('LauncherHost.cs','Client291-CharacterListBridge.bin','Client291-CloseObserver.bin')){Need ($hashes[$member] -eq $active.Files.$member) ('UNRELATED_RUNTIME_MEMBER_CHANGED_'+$member)}
Need ((Get-FileHash -LiteralPath (Join-Path $profile 'Launcher.exe') -Algorithm SHA256).Hash -eq $active.LauncherSHA) 'NEW_LAUNCHER_COPY_DIFFERS'
[IO.File]::WriteAllText((Join-Path $profile 'hashes.json'),($hashes|ConvertTo-Json),[Text.Encoding]::ASCII)
$backup=Join-Path ([Environment]::GetFolderPath('MyDocuments')) ('CABAL291-Launcher-Backups\quest-packets-'+[guid]::NewGuid().ToString('N'))
[void][IO.Directory]::CreateDirectory($backup)
[IO.File]::WriteAllBytes((Join-Path $backup 'active.json'),$before)
$active.Profile=$name;$active.Files=[pscustomobject]$hashes
$active|Add-Member -NotePropertyName QuestDungeonPackets -NotePropertyValue 'type2-scalar-v1' -Force
$after=[Text.Encoding]::UTF8.GetBytes(($active|ConvertTo-Json -Depth 32))
Need ((Sha ([IO.File]::ReadAllBytes($activePath))) -eq (Sha $before)) 'ACTIVE_PROFILE_CHANGED_DURING_BUILD'
Need (!(Get-Process -Name CabalMain -ErrorAction SilentlyContinue)) 'SPELE_PALAISTA_UZSTADISANAS_LAIKA; VECAS_PROFILS_SAGLABATS'
try{AtomicWrite $activePath $after;Need ((Sha ([IO.File]::ReadAllBytes($activePath))) -eq (Sha $after)) 'ACTIVE_READBACK_DIFFERS'}catch{AtomicWrite $activePath $before;throw}
'QUEST_DUNGEON_PACKET_FIX_INSTALLED; SPELE_NETIKA_PALAISTA'
'PALAIDEJS='+(Join-Path $profile 'Launcher.exe')
'IEPRIEKSEJAIS_PALAIDEJS='+$launcher
'REZERVES_KOPIJA='+$backup
'LABOJUMS=54_DUNGEON_NOSACIJUMU_PAKETES; PILNA_31_ATSKIRIGA_QUEST_DATU_SALAGOSANA_VEL_NAV_IEKLAUTA'
